// Greeting.jsx.
export function Greeting({ name, level = 2 }) {
  const Heading = `h${level}`;               // computed during render: fine.
  const display = name.trim() || "learner";   // new value, props untouched.
  return <Heading>Welcome back, {display}!</Heading>;
}

// Usage.
<Greeting name="Asha" />
<Greeting name="  " level={3} />

// Greeting.test.jsx.
import { render, screen } from "@testing-library/react";
it("falls back to learner for a blank name", () => {
  render(<Greeting name="  " />);
  expect(screen.getByRole("heading", { name: "Welcome back, learner!" })).toBeTruthy();
});
```

| Allowed during render | Not allowed during render |
|---|---|
| read props and state. | change props (`props.name = ...`). |
| compute new values. | change globals or module variables. |
| return JSX. | touch the DOM, fetch, set timers. |

